import sys

# Maximum value of a_i as per constraints
MAX_A = 10000000

# Precompute smallest prime factor (spf) for all numbers up to MAX_A
def precompute_spf(n):
    spf = list(range(n + 1))
    for i in range(2, int(n**0.5) + 1):
        if spf[i] == i:  # i is prime
            for j in range(i*i, n + 1, i):
                if spf[j] == j:
                    spf[j] = i
    return spf

# Precompute pi (prime counting function): pi[x] = number of primes <= x
def precompute_pi(n):
    is_prime = [True] * (n + 1)
    is_prime[0] = is_prime[1] = False
    for i in range(2, int(n**0.5) + 1):
        if is_prime[i]:
            for j in range(i*i, n + 1, i):
                is_prime[j] = False

    pi = [0] * (n + 1)
    count = 0
    for i in range(n + 1):
        if is_prime[i]:
            count += 1
        pi[i] = count
    return pi

# Precompute during initialization
spf = precompute_spf(MAX_A)
pi = precompute_pi(MAX_A)

# Function to compute Grundy number g(x)
def get_grundy(x):
    if x % 2 == 0:
        return 0
    elif x == 1:
        return 1
    else:
        # x is odd and > 1
        return pi[spf[x]]

def main():
    input_data = sys.stdin.read().split()
    idx = 0
    t = int(input_data[idx])
    idx += 1

    results = []
    for _ in range(t):
        n = int(input_data[idx])
        idx += 1

        # Read n pile sizes
        piles = []
        for _ in range(n):
            piles.append(int(input_data[idx]))
            idx += 1

        # Compute XOR of Grundy numbers
        xor_sum = 0
        for a in piles:
            xor_sum ^= get_grundy(a)

        if xor_sum != 0:
            results.append("Alice")
        else:
            results.append("Bob")

    print('\n'.join(results))

if __name__ == "__main__":
    main()
